contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function as required
    function run(uint256 fund, uint256 betAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (betAmt)); require(betAmt <= 1000000000000000000000000000000);
        // need funds to send wager amount
        require(address(this).balance >= fund, "insufficient funding");
        // betAmt must equal the current bet limit to be a valid wager
        // we read currentBetLimit() from c and require input matches it
        uint256 currentLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;
        require(betAmt == currentLimit, "betAmt must equal currentBetLimit");
        // ensure we have enough balance to send the wager
        require(address(this).balance >= betAmt, "not enough ether to wager");

        uint256 beforeC = address(c).balance;

        bool wagerReverted;
        c.wager{value: betAmt}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        uint256 afterC = address(c).balance;
        bool hasWager = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        // If wager succeeded (did not revert) then the contract balance must increase by exactly betAmt
        // and hasPlayerWagered(this) must be true. If wager reverted then nothing is required here.
        assert(
            wagerReverted
            || (
                !wagerReverted
                && hasWager
                && afterC == beforeC + betAmt
            )
        );
    }

    receive() external payable {}
}

