pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 fund, uint256 betAmt) internal {
        betAmt = bound(betAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        uint256 currentLimit;
        try c.currentBetLimit() returns (uint256 __r) { currentLimit = __r; } catch { return; }
        betAmt = currentLimit;
        vm.assume(address(this).balance >= betAmt);
        uint256 beforeC = address(c).balance;
        bool wagerReverted;
        try c.wager{value: betAmt}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        uint256 afterC = address(c).balance;
        bool hasWager;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { hasWager = __r; } catch { return; }
        assertTrue(wagerReverted
            || (
                !wagerReverted
                && hasWager
                && afterC == beforeC + betAmt
            ));
    }

    function testFuzz_run(uint256 fund, uint256 betAmt) public {
        _run(fund, betAmt);
    }

    receive() external payable {}
}
